CREATE MATERIALIZED VIEW silver.session_minute_sate_adv_mv TO silver.session_minute_sate_adv (`video_session_id` FixedString(64), `user_id` FixedString(64), `bucket_start` DateTime('UTC'), `has_active_event` SimpleAggregateFunction(max, UInt8), `has_stop_event` SimpleAggregateFunction(max, UInt8), `first_active_at` SimpleAggregateFunction(min, DateTime64(3, 'UTC')), `last_active_at` SimpleAggregateFunction(max, DateTime64(3, 'UTC')), `first_stop_at` SimpleAggregateFunction(min, DateTime64(3, 'UTC')), `last_stop_at` SimpleAggregateFunction(max, DateTime64(3, 'UTC'))) AS SELECT video_session_id, user_id, toStartOfMinute(event_timestamp) AS bucket_start, maxSimpleState(if((event IN ('VideoSessionStart', 'Play', 'resume', 'next_video_click', 'AdResume')), 1, 0)) AS has_active_event, maxSimpleState(if((event IN ('pause', 'AppBackgrounded', 'VideoSessionEnd', 'VideoError', 'AdPause', 'AdClick')), 1, 0)) AS has_stop_event, minSimpleState(if((event IN ('VideoSessionStart', 'Play', 'resume', 'next_video_click', 'AdResume')), event_timestamp, toDateTime64('9999-12-31 23:59:59', 3, 'UTC'))) AS first_active_at, maxSimpleState(if((event IN ('VideoSessionStart', 'Play', 'resume', 'next_video_click', 'AdResume')), event_timestamp, toDateTime64('1970-01-01 00:00:00', 3, 'UTC'))) AS last_active_at, minSimpleState(if((event IN ('pause', 'AppBackgrounded', 'VideoSessionEnd', 'VideoError', 'AdPause', 'AdClick')), event_timestamp, toDateTime64('9999-12-31 23:59:59', 3, 'UTC'))) AS first_stop_at, maxSimpleState(if((event IN ('pause', 'AppBackgrounded', 'VideoSessionEnd', 'VideoError', 'AdPause', 'AdClick')), event_timestamp, toDateTime64('1970-01-01 00:00:00', 3, 'UTC'))) AS last_stop_at FROM bronze.ott_events GROUP BY video_session_id, user_id, bucket_start